CREATE EXTENSION IF NOT EXISTS pg_cron;
CREATE OR REPLACE FUNCTION public.evaluation_process_schedule() RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public."Evaluation_Activities"; u public."Users"; kind text; n integer:=0; config jsonb; BEGIN SELECT s.config INTO config FROM public."Evaluation_Settings" s WHERE id='main'; FOR a IN SELECT * FROM public."Evaluation_Activities" WHERE state NOT IN ('Draft','Archived') LOOP IF a.module='marathon' AND (now()>=a.ends_at OR a.closed_at IS NOT NULL) THEN PERFORM public.evaluation_finalize(a.id); END IF; IF coalesce(config->>'notifications','true')='false' THEN CONTINUE; END IF; FOR kind IN SELECT x FROM unnest(ARRAY['published','reminder','closed']) x LOOP IF (kind='published' AND now()<coalesce(a.publish_at,a.starts_at)) OR (kind='reminder' AND (now()<a.starts_at-make_interval(hours=>coalesce((config->>'reminder_hours')::integer,24)) OR now()>=a.starts_at)) OR (kind='closed' AND now()<a.ends_at AND a.closed_at IS NULL) THEN CONTINUE; END IF; FOR u IN SELECT * FROM public."Users" WHERE coalesce("Status",'Active') NOT IN ('Pending','Suspended') AND (CASE WHEN "Role"='Leader' THEN 'Leader' ELSE 'Member' END)=a.audience AND (a.audience='Leader' OR coalesce("Team_ID",'')=ANY(a.team_ids)) AND (cardinality(a.beneficiary_ids)=0 OR "ID"=ANY(a.beneficiary_ids)) LOOP IF NOT EXISTS(SELECT 1 FROM public."User_Notifications" WHERE "User_ID"=u."ID" AND "Source"='evaluation_'||kind AND "Reference_ID"=a.id::text) THEN INSERT INTO public."User_Notifications"("Notification_ID","User_ID","Title","Body","Created_At","Is_Read","Source","Reference_ID") VALUES(gen_random_uuid()::text,u."ID",CASE kind WHEN 'published' THEN 'نشاط جديد متاح' WHEN 'reminder' THEN 'تذكير باقتراب النشاط' ELSE 'تم إغلاق النشاط' END,a.title,now()::text,'False','evaluation_'||kind,a.id::text); n:=n+1; END IF; END LOOP; END LOOP; END LOOP; RETURN n; END $$;
CREATE OR REPLACE FUNCTION public.evaluation_notify_result() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE a public."Evaluation_Activities"; BEGIN IF EXISTS(SELECT 1 FROM public."Evaluation_Settings" WHERE id='main' AND config->>'notifications'='false') THEN RETURN NEW; END IF; SELECT * INTO a FROM public."Evaluation_Activities" WHERE id=NEW.activity_id; INSERT INTO public."User_Notifications"("Notification_ID","User_ID","Title","Body","Created_At","Is_Read","Source","Reference_ID") VALUES(gen_random_uuid()::text,NEW.user_id,CASE WHEN a.module IN ('church','scout') THEN 'تم تسجيل الحضور' WHEN a.module='notebook' THEN 'تم تقييم النوتة الروحية' WHEN a.module='marathon' THEN 'تم استلام إجابات المسابقة' ELSE 'تم تسجيل التقييم' END,a.title,now()::text,'False','evaluation_result',NEW.id::text); RETURN NEW; END $$;
CREATE TRIGGER evaluation_notify_result_after AFTER INSERT ON public."Evaluation_Results" FOR EACH ROW EXECUTE FUNCTION public.evaluation_notify_result();
CREATE OR REPLACE FUNCTION public.evaluation_guard_criteria() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE aid uuid; BEGIN aid:=CASE WHEN TG_OP='DELETE' THEN OLD.activity_id ELSE NEW.activity_id END; IF EXISTS(SELECT 1 FROM public."Evaluation_Activities" WHERE id=aid AND state<>'Draft') THEN IF TG_OP<>'INSERT' OR EXISTS(SELECT 1 FROM public."Evaluation_Results" WHERE activity_id=aid) THEN RAISE EXCEPTION 'Published criteria immutable'; END IF; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER evaluation_criteria_guard BEFORE UPDATE OR DELETE ON public."Evaluation_Criteria" FOR EACH ROW EXECUTE FUNCTION public.evaluation_guard_criteria();
REVOKE ALL ON FUNCTION public.evaluation_process_schedule(),public.evaluation_notify_result(),public.evaluation_guard_criteria() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.evaluation_process_schedule() TO service_role;